function usageErrorReason(code?:string|null){const value=String(code||'').trim();if(!value)return '未记录错误详情';const known:Record<string,string>={upstream_connection:'无法连接上游模型服务',invalid_upstream_response:'上游响应格式无效',client_cancelled:'客户端取消了请求',usage_missing:'上游未返回计费用量信息',stream_usage_missing:'流式响应未返回计费用量信息'};if(known[value])return known[value];const upstream=value.match(/^upstream_http_(\d{3})$/);if(upstream)return `上游返回 HTTP ${upstream[1]}，未提供具体错误信息`;return value}
const fmtDateTime = (value?:string) => { if(!value)return '—'; const raw=value.includes('T')?value:value.replace(' ','T'); const date=new Date(/[zZ]|[+-]\d{2}:?\d{2}$/.test(raw)?raw:`${raw}Z`); return Number.isNaN(date.getTime())?value:new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(date) }
const shanghaiParts = (date:Date) => Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(date).filter(x=>x.type!=='literal').map(x=>[x.type,Number(x.value)])) as {year:number;month:number;day:number;hour:number;minute:number;second:number}
