type ExampleLanguage = 'curl'|'python'|'typescript'|'javascript'
function modelExample(model:any,baseUrl:string,language:ExampleLanguage){
  const protocol=String(model?.protocol||'openai').toLowerCase()
  const modelKey=JSON.stringify(model?.model_key||'MODEL_NAME')
  const key='YOUR_API_KEY'
  if(protocol==='anthropic'){
    const endpoint=`${baseUrl}/v1/messages`
    if(language==='curl')return `curl ${endpoint} \\\n  -H "x-api-key: <${key}>" \\\n  -H "anthropic-version: 2023-06-01" \\\n  -H "Content-Type: application/json" \\\n  -d '{"model": ${modelKey}, "max_tokens": 512, "messages": [{"role": "user", "content": "你好，请介绍一下自己。"}]}'`
    if(language==='python')return `import anthropic\n\nclient = anthropic.Anthropic(\n    api_key="<${key}>",\n    base_url=${JSON.stringify(baseUrl)},\n)\nmessage = client.messages.create(\n    model=${modelKey},\n    max_tokens=512,\n    messages=[{"role": "user", "content": "你好，请介绍一下自己。"}],\n)\nprint(message.content[0].text)`
    return `import Anthropic from "@anthropic-ai/sdk";\n\nconst client = new Anthropic({\n  apiKey: "<${key}>",\n  baseURL: ${JSON.stringify(baseUrl)},\n});\nconst message = await client.messages.create({\n  model: ${modelKey},\n  max_tokens: 512,\n  messages: [{ role: "user", content: "你好，请介绍一下自己。" }],\n});\nconsole.log(message.content[0].type === "text" ? message.content[0].text : message.content);`
  }
  if(protocol==='dashscope'){
    if(String(model?.model_key||'').toLowerCase()==='happyhorse-1.1-t2v'){
      const endpoint=`${baseUrl}/api/v1/services/aigc/video-generation/video-synthesis`
      const task=`${baseUrl}/api/v1/tasks/{task_id}`
      const payload=JSON.stringify({model:model?.model_key||'happyhorse-1.1-t2v',input:{prompt:'一只橘猫在草地上奔跑，阳光明媚'},parameters:{size:'1920*1080',duration:5}})
      if(language==='curl')return `# 创建异步视频任务\ncurl --location '${endpoint}' -H "Authorization: Bearer <${key}>" -H 'Content-Type: application/json' --data '${payload}'\n\n# 使用返回的 task_id 轮询状态\ncurl --location '${task}' --header "Authorization: Bearer <${key}>"`
      if(language==='python')return `import time\nimport requests\n\nbase_url = ${JSON.stringify(baseUrl)}\nheaders = {"Authorization": "Bearer <${key}>", "Content-Type": "application/json"}\npayload = {"model": ${modelKey}, "input": {"prompt": "一只橘猫在草地上奔跑，阳光明媚"}, "parameters": {"size": "1920*1080", "duration": 5}}\ntask = requests.post(base_url + "/api/v1/services/aigc/video-generation/video-synthesis", headers=headers, json=payload).json()\ntask_id = task["task_id"]\nwhile True:\n    result = requests.get(base_url + "/api/v1/tasks/" + task_id, headers=headers).json()\n    status = result.get("output", {}).get("task_status")\n    if status == "SUCCEEDED":\n        print(result["output"]["video_url"]); break\n    if status in ("FAILED", "CANCELED", "CANCELLED"):\n        raise RuntimeError(result)\n    time.sleep(5)`
      return `const baseUrl = ${JSON.stringify(baseUrl)};\nconst headers = { "Authorization": "Bearer <${key}>", "Content-Type": "application/json" };\nconst taskResponse = await fetch(baseUrl + "/api/v1/services/aigc/video-generation/video-synthesis", { method: "POST", headers, body: JSON.stringify({ model: ${modelKey}, input: { prompt: "一只橘猫在草地上奔跑，阳光明媚" }, parameters: { size: "1920*1080", duration: 5 } }) });\nconst task = await taskResponse.json();\nconst result = await fetch(baseUrl + "/api/v1/tasks/" + task.task_id, { headers }).then(r => r.json());\nconsole.log(result);`
    }
    const endpoint=`${baseUrl}/api/v1/services/aigc/text-generation/generation`
    const payload=`{\n  "model": ${modelKey},\n  "input": { "messages": [{ "role": "user", "content": "你好，请介绍一下自己。" }] },\n  "parameters": { "result_format": "message" }\n}`
    if(language==='curl')return `curl ${endpoint} \\\n  -H "Authorization: Bearer <${key}>" \\\n  -H "Content-Type: application/json" \\\n  -d '${payload.replaceAll("'", "'\\''")}'`
    if(language==='python')return `import requests\n\nresponse = requests.post(\n    ${JSON.stringify(endpoint)},\n    headers={"Authorization": "Bearer <${key}>"},\n    json=${payload.replaceAll('\n','\n    ')},\n)\nresponse.raise_for_status()\nprint(response.json())`
    return `const response = await fetch(${JSON.stringify(endpoint)}, {\n  method: "POST",\n  headers: {\n    "Authorization": "Bearer <${key}>",\n    "Content-Type": "application/json",\n  },\n  body: JSON.stringify(${payload.replaceAll('\n','\n  ')}),\n});\nif (!response.ok) throw new Error(await response.text());\nconsole.log(await response.json());`
  }
  const endpoint=`${baseUrl}/v1/chat/completions`
  if(language==='curl')return `curl ${endpoint} \\\n  -H "Authorization: Bearer <${key}>" \\\n  -H "Content-Type: application/json" \\\n  -d '{"model": ${modelKey}, "messages": [{"role": "user", "content": "你好，请介绍一下自己。"}], "temperature": 0.7}'`
  if(language==='python')return `from openai import OpenAI\n\nclient = OpenAI(\n    api_key="<${key}>",\n    base_url=${JSON.stringify(`${baseUrl}/v1`)},\n)\nresponse = client.chat.completions.create(\n    model=${modelKey},\n    messages=[{"role": "user", "content": "你好，请介绍一下自己。"}],\n    temperature=0.7,\n)\nprint(response.choices[0].message.content)`
  const ts=language==='typescript'
  return `import OpenAI from "openai";\n\nconst client = new OpenAI({\n  apiKey: "<${key}>",\n  baseURL: ${JSON.stringify(`${baseUrl}/v1`)},\n});\n${ts?'const prompt: string = ':'const prompt = '}"你好，请介绍一下自己。";\nconst response = await client.chat.completions.create({\n  model: ${modelKey},\n  messages: [{ role: "user", content: prompt }],\n  temperature: 0.7,\n});\nconsole.log(response.choices[0].message.content);`
}
function PasswordInput(props: InputHTMLAttributes<HTMLInputElement>) {
  const [visible, setVisible] = useState(false)
  return <span className="password-input-wrap"><input {...props} type={visible ? 'text' : 'password'} /><button type="button" className="password-visibility-toggle" aria-label={visible ? '隐藏密码' : '显示密码'} title={visible ? '隐藏密码' : '显示密码'} onClick={() => setVisible(value => !value)}>{visible ? <EyeOff size={17}/> : <Eye size={17}/>}</button></span>
}

