  useEffect(()=>{
    if(!token)return
    let timeout=0
    const checkExpiry=()=>{
      try{
        const encoded=token.split('.')[1]
        if(!encoded)throw new Error('登录令牌无效')
        const payload=JSON.parse(atob(encoded.replace(/-/g,'+').replace(/_/g,'/')))
        const expiresAt=Number(payload.exp)*1000
        if(!Number.isFinite(expiresAt)||expiresAt<=Date.now()){logout(true);return}
        window.clearTimeout(timeout)
        timeout=window.setTimeout(()=>logout(true),expiresAt-Date.now())
      }catch{logout(true)}
    }
    checkExpiry()
    document.addEventListener('visibilitychange',checkExpiry)
    return()=>{window.clearTimeout(timeout);document.removeEventListener('visibilitychange',checkExpiry)}
  },[token])
