  async function addPlaygroundFiles(files:FileList|null){if(!files)return;const accepted:any[]=[];for(const file of Array.from(files)){const ext=file.name.split('.').pop()?.toLowerCase()||'';if(file.size>7*1024*1024){toast(`${file.name} 超过 7 MB，无法上传`);continue}if(playgroundAttachments.reduce((n,a)=>n+Number(a.size||0),0)+accepted.reduce((n,a)=>n+Number(a.size||0),0)+file.size>10*1024*1024){toast('单次附件总大小不能超过 10 MB');continue}if(file.type.startsWith('image/')){if(!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type)){toast(`${file.name}：仅支持 PNG、JPEG、WebP、GIF 图片`);continue}const dataUrl=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=()=>reject(new Error('读取图片失败'));reader.readAsDataURL(file)});let previewUrl='';try{const bitmap=await createImageBitmap(file);const scale=Math.min(1,800/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d')?.drawImage(bitmap,0,0,canvas.width,canvas.height);previewUrl=canvas.toDataURL('image/webp',.7);bitmap.close()}catch{}accepted.push({name:file.name,kind:'image',mime:file.type,dataUrl,previewUrl,size:file.size})}else if(['txt','md','csv','json','log','xml','yaml','yml'].includes(ext)||file.type.startsWith('text/')){if(file.size>2*1024*1024){toast(`${file.name} 超过 2 MB，无法作为文本读取`);continue}try{accepted.push({name:file.name,kind:'file',text:await file.text(),size:file.size})}catch{toast(`${file.name} 读取失败`)}}else toast(`${file.name} 暂不支持，请上传图片或 TXT、Markdown、CSV、JSON 等文本文件`)}if(accepted.length)setPlaygroundAttachments(v=>[...v,...accepted].slice(0,8));if(playgroundFileRef.current)playgroundFileRef.current.value=''}
  function openPlaygroundAttachment(message:any,attachment:any){let text=attachment.text||'';if(!text&&attachment.kind==='file'){const source=message.apiContent?.find((b:any)=>b.type==='text')?.text||'';const marker=`[文件：${attachment.name}]\n`;const start=source.indexOf(marker);if(start>=0){const rest=source.slice(start+marker.length);const next=rest.search(/\n\n\[文件：/);text=next>=0?rest.slice(0,next):rest}}setAttachmentPreview({...attachment,dataUrl:attachment.dataUrl||attachment.previewUrl,text})}
