    const attachments=activeAttachments.map((a:any)=>({...a}));
    const userMessage=replay?.message?{...replay.message,attachments,agent_mode:useAgent}:{role:'user',content:prompt||'请查看附件并回答。',apiContent,attachments,agent_mode:useAgent,model_key:selectedPlaygroundModel.model_key,time:new Date().toLocaleTimeString('zh-CN',{hour12:false})};
