        if(!response.ok){const data=await response.json().catch(()=>({}));throw new Error((typeof data.error==='string'?data.error:data.error?.message)||data.message||`Agent 请求失败（HTTP ${response.status}）`)}
        if(!response.body)throw new Error('浏览器无法读取 Agent 流式响应');const reader=response.body.getReader();const decoder=new TextDecoder();let buffer='';let agentUsage:any;let agentTruncated=false;
        const handleAgentLine=(line:string)=>{const raw=line.trimEnd().replace(/\r$/,'');if(!raw.startsWith('data:'))return;const data=raw.slice(5).trim();if(!data||data==='[DONE]')return;let event:any;try{event=JSON.parse(data)}catch{return}if(event.type==='error'||event.error)throw new Error(event.error?.message||event.error||'Agent 执行失败');if(event.type==='content'){answer+=String(event.delta||'')}else if(event.type==='reasoning'){reasoning+=String(event.delta||'')}else if(event.type==='tool_start'){toolActivity.push({name:event.name||'run_python',code:String(event.code||''),output:'正在云端沙盒执行…',exitCode:-1})}else if(event.type==='tool_result'){const activity=[...toolActivity].reverse().find((x:any)=>x.name===(event.name||'run_python')&&x.code===String(event.code||'')&&x.exitCode===-1);if(activity){activity.output=String(event.output||'');activity.exitCode=Number(event.exit_code??-1)}else toolActivity.push({name:event.name||'run_python',code:String(event.code||''),output:String(event.output||''),exitCode:Number(event.exit_code??-1)})}else if(event.type==='done'){agentUsage=event.usage;agentTruncated=Boolean(event.truncated)}setPlaygroundMessages(v=>v.map((m,i)=>i===assistantIndex?{...m,content:answer,reasoning,toolActivity:[...toolActivity]}:m))};
