  async function refreshCaptcha(){setCaptchaLoading(true);try{const r=await fetch(`${API}/api/auth/captcha`);const data=await r.json().catch(()=>({}));if(!r.ok)throw new Error(data.error||'验证码加载失败');setCaptchaId(data.captcha_id||'');setCaptchaImage(data.image||'');setCaptchaAnswer('')}catch(err){setCaptchaId('');setCaptchaImage('');toast(err instanceof Error?err.message:'验证码加载失败，请刷新页面重试')}finally{setCaptchaLoading(false)}}
  async function login(e:React.FormEvent<HTMLFormElement>){e.preventDefault();if(!captchaId||!captchaAnswer.trim()){toast('请先完成图像验证码');return}try{const r=await fetch(`${API}/api/auth/login`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({account:loginAccount.trim(),password:loginPassword,captcha_id:captchaId,captcha:captchaAnswer})});const data=await r.json().catch(()=>({}));if(!r.ok)throw new Error(data.error||'登录失败，请检查账号和密码');const x=data;localStorage.setItem('llmroute_token',x.token);localStorage.setItem('llmroute_user',JSON.stringify(x.user));setToken(x.token);setUser(x.user);setLoginPassword('');setCaptchaAnswer('');setModal(null);setShowLogin(false);toast('登录成功')}catch(err){toast(err instanceof Error?err.message:'登录失败，请检查账号和密码');void refreshCaptcha()}}
