  async function refreshApiKeys(){if(!token||apiKeysRefreshing)return;setApiKeysRefreshing(true);try{const r=await fetch(`${API}/api/api-keys`,{headers:{Authorization:`Bearer ${token}`}});const data=await r.json().catch(()=>[]);if(!r.ok)throw new Error(data.error||'API 密钥刷新失败');setApiKeys(Array.isArray(data)?data:[]);if(selectedApiKeyId){const stats=await fetch(`${API}/api/api-keys/${selectedApiKeyId}/stats`,{headers:{Authorization:`Bearer ${token}`}});if(stats.ok)setApiKeyStats(await stats.json())}toast('API 密钥已刷新')}catch(err){toast(err instanceof Error?err.message:'API 密钥刷新失败')}finally{setApiKeysRefreshing(false)}}
