  function downloadBatchTemplate(){const csv='姓名,账号,手机号,部门名称,角色,个人月度额度（元）,邮箱\n';const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));a.download='成员批量导入模板.csv';a.click();URL.revokeObjectURL(a.href)}
  async function submitBatchImport(){const rows=parseCsvRows(batchCsv);if(rows.length<2){toast('请先选择或填写包含成员信息的 CSV');return}const dataRows=rows[0].some(x=>x.includes('姓名')||x.includes('账号'))?rows.slice(1):rows;const payload=dataRows.filter(r=>r.some(x=>x.trim())).map(r=>({display_name:r[0]||'',username:r[1]||'',phone:r[2]||'',email:r[6]||'',department_id:deps.find(d=>d.name===(r[3]||'').trim())?.id||'',role:['部门管理员','department_admin'].includes((r[4]||'').trim())?'department_admin':['','普通用户','user'].includes((r[4]||'').trim())?'user':(r[4]||'').trim(),personal_limit_cents:(r[5]||String(settingValues.default_member_limit_cents/100)).trim()===''?settingValues.default_member_limit_cents:Number.isFinite(Number((r[5]||String(settingValues.default_member_limit_cents/100)).trim()))?Math.round(Number((r[5]||String(settingValues.default_member_limit_cents/100)).trim())*100):-1}));if(!payload.length){toast('CSV 中没有成员行');return}try{const r=await fetch(`${API}/api/users/batch`,{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify({users:payload})});const result=await r.json().catch(()=>({}));if(!r.ok)throw new Error(result.error||'批量导入失败');setBatchResults(result.results||[]);const usersRes=await fetch(`${API}/api/users`,{headers:{Authorization:`Bearer ${token}`}});if(usersRes.ok)setUsers((await usersRes.json()).map((x:any)=>({...x,used:Number(x.used||0)})));toast(`批量导入完成：成功 ${result.succeeded||0}，失败 ${result.failed||0}`)}catch(err){toast(err instanceof Error?err.message:'批量导入失败')}}
