  async function saveUser(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);const item={display_name:String(f.get('display_name')),username:String(f.get('username')),department_id:String(f.get('department_id')||''),role:String(f.get('role')),phone:String(f.get('phone')||'').trim(),email:String(f.get('email')||'').trim(),personal_limit_cents:Math.round(Number(f.get('personal_limit'))*100)};try{const r=await fetch(`${API}/api/users`,{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify(item)});if(!r.ok){const data=await r.json().catch(()=>({}));throw new Error(data.error||data.message||'成员创建失败')}const usersRes=await fetch(`${API}/api/users`,{headers:{Authorization:`Bearer ${token}`}});if(usersRes.ok)setUsers((await usersRes.json()).map((x:any)=>({...x,used:Number(x.used||0)})));setModal(null);toast('成员已创建；初始密码由系统初始化配置提供')}catch(err){toast(err instanceof Error?err.message:'成员创建失败')}}
